  display: block;
  margin-bottom: var(--space-1);
  font-size: 14px;
  font-weight: 600;
}

.form-input {
  display: block;
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-md);
  background: var(--color-surface);
  font: inherit;
  font-size: 15px;
  color: var(--color-ink);
}

textarea.form-input {
  min-height: 120px;
  resize: vertical;
}

.form-input:focus {
  outline: 2px solid var(--color-brand);
  outline-offset: 1px;
}

.form-input.is-invalid {
  border-color: var(--color-danger);
}

.form-error {
  margin-top: var(--space-1);
  font-size: 13px;
  color: var(--color-danger);
}

.form-check {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  font-size: 14px;
}

.form-check input {
  margin: 3px 0 0;
}

.form-inline {
  display: flex;
  gap: var(--space-2);
}

.form-inline .form-input {
  flex: 1;
  min-width: 0;
}

/* Table */

.table-wrap {
  overflow-x: auto;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-lg);
  background: var(--color-surface);
}

.table {
  width: 100%;
  font-size: 14px;
  color: var(--color-muted);
}

.pager {
  display: flex;
  gap: var(--space-2);
}

/* Contact */

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: var(--space-6);
  align-items: start;
}

.info-list dt {
  margin-top: var(--space-4);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--color-muted);
}

.info-list dt:first-child {
  margin-top: 0;
}

/* About */

.story {
  display: grid;
  grid-template-columns: 1fr 480px;
  gap: var(--space-7);
  align-items: center;
}

.story p + p {
  margin-top: var(--space-4);
}

.story-art {
  border-radius: var(--radius-lg);
}

.avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: var(--space-3);
  border-radius: 50%;
  background: var(--color-brand-tint);
  font-size: 18px;
  font-weight: 800;
  color: var(--color-brand-dark);
}

.timeline {
  padding-left: var(--space-5);
  border-left: 2px solid var(--color-line);
}

.timeline-item {
  position: relative;
  padding-bottom: var(--space-5);
}

.timeline-item:last-child {
  padding-bottom: 0;
}

.timeline-item::before {
  content: '';
  position: absolute;
  top: 5px;
  left: -32px;
  width: 12px;
  height: 12px;
  border: 2px solid var(--color-surface);
  border-radius: 50%;
  background: var(--color-brand);
}

.timeline-year {
  font-weight: 800;
  color: var(--color-brand);
}

.cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  padding: var(--space-6);
  border-radius: var(--radius-lg);
  background: var(--color-ink);
  color: #ffffff;
}

.cta p {
  margin-top: var(--space-1);
  color: #c9d1d9;
}

@media (max-width: 720px) {
  .hero {
    padding-top: var(--space-7);
  }

  .hero-inner,
  .feature,
  .newsletter,
  .bundles,
  .plans,
  .faq,
  .contact-grid,
  .story {
    grid-template-columns: 1fr;
  }

  .hero-copy h1 {
    font-size: 32px;
  }

  .feature-copy {
    padding: 0 var(--space-5) var(--space-5);
  }

  .feature-art {
    height: 160px;
  }

  .newsletter {
    padding: var(--space-5);
  }

  .cta {
    flex-direction: column;
    align-items: flex-start;
  }
}
